import * as React from "react"

function HeroWithVideoBackground2({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="hero-with-video-background-2"
      className={className}
      {...props}
    >
      <style>{".video-docker video {\r\n        top: 50%;\r\n        left: 50%;\r\n        transform: translate(-50%, -50%);\r\n    }\r\n\r\n    .video-docker::after {\r\n        content: \"\";\r\n        position: absolute;\r\n        width: 100%;\r\n        height: 100%;\r\n        top: 0;\r\n        left: 0;\r\n        background: rgba(0, 0, 0, 0.6);\r\n        z-index: 1;\r\n    }"}</style>
      
      
      <section className="relative h-screen flex flex-col items-center justify-center text-center text-white ">
          <div className="video-docker absolute top-0 left-0 w-full h-full overflow-hidden">
              <video className="min-w-full min-h-full absolute object-cover"
                  src="https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerJoyrides.mp4"
                  type="video/mp4" autoplay muted loop></video>
          </div>
          <div className="video-content space-y-2 z-10">
              <h1 className="font-light text-6xl">Chinook Digital Media</h1>
              <h3 className="font-light text-3xl my-6">As streaming, social, and gaming converge, companies should
                      consider comprehensive strategies to define media and
                      entertainment's future—or they could risk living in someone
                      else’s vision.</h3>
          </div>
      </section>
    </div>
  )
}

export { HeroWithVideoBackground2 }
